import assert from "node:assert/strict";
import http from "node:http";
import { mkdtempSync } from "node:fs";
import { join } from "node:path";

const dir = mkdtempSync(join(process.env.TMPDIR ?? "/tmp", "drop-approval-"));
process.env.DATA_DIR = dir;

const { Agent } = await import("@mastra/core/agent");
const { createTool } = await import("@mastra/core/tools");
const { toAISdkMessages } = await import("@mastra/ai-sdk/ui");
const { isToolUIPart } = await import("ai");
const { MockLanguageModelV3 } = await import("ai/test");
const { z } = await import("zod");
const { mastra } = await import("./src/mastra");
const { memory } = await import("./src/mastra/memory");
const { handleChat } = await import("./src/chat-api");
const { pendingApprovalIds } = await import("./src/chat-approvals");

const executed: string[] = [];
const createIssue = createTool({
  id: "create_issue",
  description: "create issue",
  inputSchema: z.object({ title: z.string().optional() }),
  requireApproval: true,
  execute: async () => {
    executed.push("create_issue");
    return { ok: true };
  },
});

const usage = { inputTokens: { total: 1, noCache: 1, cacheRead: 0, cacheWrite: 0 }, outputTokens: { total: 1, text: 1, reasoning: 0 } };
const text = (t: string) => [{ type: "text-start", id: "t" }, { type: "text-delta", id: "t", delta: t }, { type: "text-end", id: "t" }];
let next: any[] = [];
const model = new MockLanguageModelV3({
  doStream: async () => {
    const parts = next;
    next = text("Fallback.");
    const finishReason = { unified: parts[0].type === "tool-call" ? "tool-calls" : "stop", raw: undefined };
    return {
      stream: new ReadableStream({
        start(c) {
          c.enqueue({ type: "stream-start", warnings: [] });
          for (const p of parts) c.enqueue(p);
          c.enqueue({ type: "finish", finishReason, usage });
          c.close();
        },
      }),
    } as any;
  },
});
mastra.addAgent(
  new Agent({ id: "mock-gh", name: "Mock GH", instructions: "test", model, memory, tools: { create_issue: createIssue }, defaultOptions: { maxSteps: 4 } }),
  "mockGh",
);

const user = { id: "u1", name: "U", username: "u", role: "member" } as any;
const server = http.createServer((req, res) => void handleChat("mockGh", req, res, user));
await new Promise<void>((r) => server.listen(0, "127.0.0.1", r));
const url = `http://127.0.0.1:${(server.address() as any).port}/`;
const post = async (message: unknown) => {
  const r = await fetch(url, { method: "POST", body: JSON.stringify({ message }) });
  return { status: r.status, body: await r.text() };
};
const ids = { threadId: "u1:mock-gh", resourceId: "u1" };
const stored = async () => (await memory.recall({ ...ids, perPage: false })).messages;
const workflows = await mastra.getStorage()!.getStore("workflows");

// 1. Write call suspends for approval.
next = [{ type: "tool-call", toolCallId: "call-write", toolName: "create_issue", input: JSON.stringify({ title: "Hi" }) }];
const r1 = await post({ id: "m1", role: "user", parts: [{ type: "text", text: "open an issue" }] });
assert.equal(r1.status, 200);
const approvalId = /"approvalId":"([^"]+)"/.exec(r1.body)?.[1];
assert.ok(approvalId, "stream carries tool-approval-request");
const runId = approvalId.split("::")[0];
assert.ok(pendingApprovalIds(await stored()).has(approvalId), "pending approval stored");
assert.ok(await workflows!.loadWorkflowSnapshot({ workflowName: "agentic-loop", runId }), "suspended run snapshot exists");
assert.deepEqual(executed, []);
console.log("1. approval pending:", approvalId, "(snapshot present)");

// 2. New user message drops it.
next = text("OK, skipping that.");
const r2 = await post({ id: "m2", role: "user", parts: [{ type: "text", text: "never mind" }] });
assert.equal(r2.status, 200);
assert.ok(r2.body.includes("OK, skipping that."), "new turn streamed");
const after = await stored();
assert.equal(pendingApprovalIds(after).size, 0, "pending approvals cleared in storage");
assert.ok(after.every((m) => !(m.content.metadata as any)?.pendingToolApprovals), "metadata key gone");
assert.equal(await workflows!.loadWorkflowSnapshot({ workflowName: "agentic-loop", runId }), null, "suspended run snapshot deleted");
const history = toAISdkMessages(after, { version: "v7" });
const states = history.map((m) => `${m.role}:${m.parts.filter(isToolUIPart).map((p) => p.state).join("|")}`);
assert.ok(!history.some((m) => m.parts.some((p) => isToolUIPart(p) && p.state === "approval-requested")), "reload offers no approval");
console.log("2. new message: pending cleared, snapshot deleted; history tool states:", states.join("  "));

// 3. Late approval of the old id is rejected; the write never runs.
const late = await post({
  id: "a1",
  role: "assistant",
  parts: [{ type: "tool-create_issue", toolCallId: "call-write", state: "approval-responded", input: { title: "Hi" }, approval: { id: approvalId, approved: true } }],
});
assert.equal(late.status, 409, "late approval rejected");
assert.deepEqual(executed, [], "write tool never ran");
console.log("3. late approval ->", late.status, late.body, "| executed:", executed);

server.close();
console.log("ALL CHECKS PASSED");
process.exit(0);

