const history = toAISdkMessages(after, { version: "v7" });
const states = history.map((m) => `${m.role}:${m.parts.filter(isToolUIPart).map((p) => p.state).join("|")}`);
assert.ok(!history.some((m) => m.parts.some((p) => isToolUIPart(p) && p.state === "approval-requested")), "reload offers no approval");
