const late = await post({
  id: "a1",
  role: "assistant",
  parts: [{ type: "tool-create_issue", toolCallId: "call-write", state: "approval-responded", input: { title: "Hi" }, approval: { id: approvalId, approved: true } }],
});
assert.equal(late.status, 409, "late approval rejected");
assert.deepEqual(executed, [], "write tool never ran");
console.log("3. late approval ->", late.status, late.body, "| executed:", executed);

server.close();
console.log("ALL CHECKS PASSED");
process.exit(0);

